{"meetingId": "852", "tickets": [
{"title": "Build shared inheritance tracking ledger", "text": "Build a shared tracking ledger for Nadia Thimblefern covering inherited accounts, estate contacts, forms received, ownership notes, and open questions so she can discuss Alden Thimblefern's estate with co-personal representative Rowan Thimblefern using the same record set.", "priority": null, "dueDate": "2024-02-23", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Nadia asked for a shared tracking ledger for inherited accounts, estate contacts, forms received, ownership notes, and open questions so she can discuss the estate with Rowan using the same record set; they agreed to build it by 2024-02-23."},
{"title": "Obtain certified probate authority paperwork for portal", "text": "Obtain the certified probate authority paperwork needed by the custodian and bank for Nadia Thimblefern's inheritance of Alden Thimblefern's estate and upload it to the secure portal; only death certificate copies from Pocket Lantern Law have been provided so far.", "priority": null, "dueDate": "2024-02-20", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the certified authority paperwork needed by the custodian and bank has not been uploaded to the secure portal; the agreed follow-up is due 2024-02-20."},
{"title": "Resolve estate account access at Teacup Comet Bank", "text": "Resolve Nadia Thimblefern's rejected online estate-account access at Teacup Comet Bank, where the executor record does not match the bank's internal file, so she can view recent estate cash activity for Alden Thimblefern's estate.", "priority": null, "dueDate": "2024-02-16", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Teacup Comet Bank rejected Nadia's online estate-account access attempt and told her the executor record did not match its internal file, preventing her from viewing recent estate cash activity; the agreed follow-up on the estate bank access problem is due 2024-02-16."},
{"title": "Confirm Alden Thimblefern's IRA beneficiary designation", "text": "Confirm the controlling beneficiary designation for Alden Thimblefern's traditional IRA, since the paper beneficiary copy Nadia Thimblefern brought does not match the percentage shown in the custodian portal, before any inherited IRA paperwork is signed.", "priority": null, "dueDate": null, "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Nadia brought a paper beneficiary copy that does not match the percentage shown in the custodian portal, and the controlling designation needs to be confirmed before inherited IRA paperwork is signed; follow-up is needed, with no date supplied."},
{"title": "Organize estate inventory and income items for advisors", "text": "Organize the estate inventory, anticipated income items, and beneficiary distributions for Nadia Thimblefern for CPA Iris Dewspindle of Amber Teapot Tax and estate attorney Galen Nettlewhisk of Pocket Lantern Law before the next tax-planning conversation tied to the estate administration calendar.", "priority": null, "dueDate": "2024-03-01", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The estate inventory, anticipated income items, and beneficiary distributions need to be organized for the CPA and estate attorney before the next tax-planning conversation tied to the estate administration calendar; the agreed follow-up is due 2024-03-01."},
{"title": "Update stale fiduciary appointment in estate documents", "text": "Update Nadia and Omar Pebblefizz's 2016 personal estate documents, which name Alden Thimblefern as a successor fiduciary, a stale appointment after his death.", "priority": null, "dueDate": "2024-03-08", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The planning review found the 2016 personal estate documents' reference to Alden in a successor fiduciary role creates a stale appointment after his death; the agreed follow-up on the fiduciary role update is due 2024-03-08."},
{"title": "Prepare inherited asset investment and spending framework", "text": "Prepare a separate investment and spending framework for Nadia Thimblefern's inherited assets that accounts for retirement flexibility around age 62, college costs, cash reserves, and her preference not to blend estate proceeds into routine spending immediately.", "priority": null, "dueDate": "2024-03-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "Nadia wants a separate investment and spending framework for inherited assets that accounts for retirement flexibility, college costs, cash reserves, and her preference not to blend estate proceeds into routine spending immediately; the agreed follow-up is due 2024-03-15."}
]}
